import { useState } from "react";
import axios from "axios";

export default function App() {
  const [code, setCode] = useState("");
  const [explanation, setExplanation] = useState("");
  const [loading, setLoading] = useState(false);

  const explainCode = async () => {
    if (!code.trim()) return;

    setLoading(true);
    setExplanation("");

    try {
      const res = await axios.post("http://127.0.0.1:8000/explain", {
        code,
      });

      setExplanation(res.data.explanation);
    } catch (err) {
      setExplanation("Something went wrong. Try again.");
    }

    setLoading(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-6">
      <div className="w-full max-w-4xl space-y-6">

        {/* Header */}
        <h1 className="text-4xl font-bold text-white flex items-center gap-3">
          🤖 AI Code Explainer
        </h1>
        <p className="text-slate-400">
          Paste your code and get a clear explanation instantly.
        </p>

        {/* Code Input */}
        <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
          <textarea
            className="w-full h-48 bg-transparent text-slate-100 font-mono text-sm outline-none resize-none"
            placeholder="Paste your code here..."
            value={code}
            onChange={(e) => setCode(e.target.value)}
          />
        </div>

        {/* Action Button */}
        <button
          onClick={explainCode}
          disabled={loading}
          className="px-6 py-3 rounded-lg bg-blue-500 hover:bg-blue-600 transition text-white font-semibold disabled:opacity-50"
        >
          {loading ? "AI is thinking..." : "Explain Code"}
        </button>

        {/* Output */}
        {explanation && (
          <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
            <h3 className="text-lg font-semibold mb-2 text-white">
              Explanation
            </h3>
            <p className="text-slate-300 whitespace-pre-wrap">
              {explanation}
            </p>
          </div>
        )}

      </div>
    </div>
  );
}
